description.example_query:
SELECT business_id, name, address, city, state, stars, review_count, categories
FROM business
WHERE city = 'Santa Barbara' AND categories LIKE '%Cuban%';

SELECT business_id, user_id, stars, date, useful, funny, cool, text
FROM review
WHERE business_id IN ('id1','id2','id3');

/* 先取点心相关 business_id */
SELECT business_id
FROM business
WHERE LOWER(categories) LIKE '%dim sum%'
   OR LOWER(categories) LIKE '%cantonese%'
   OR LOWER(categories) LIKE '%chinese%';

/* 再在 review 中聚合用户写了多少条 */
SELECT user_id, COUNT(*) AS dimsum_review_cnt, AVG(stars) AS avg_given
FROM review
WHERE business_id IN ( ... )
GROUP BY user_id
HAVING COUNT(*) >= 8;
